import { uploadRelatedDocument } from '@/lib/privateDocuments';
import { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  ArrowLeft, FileText, Shield, Loader2, Upload, Play, FileCheck,
  AlertTriangle, Download,
  ChevronDown, ChevronUp, Lock
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import ReactMarkdown from 'react-markdown';
import AuditInvestigationTab from '@/components/audit/AuditInvestigationTab';
import AuditHistoryTab from '@/components/audit/AuditHistoryTab';
import AuditEmailTab from '@/components/audit/AuditEmailTab';
import { exportReportToPDF, exportReportToDOCX } from '@/lib/auditReportExport';

const VERDICT_LABELS = {
  ok: { label: 'OK', color: 'bg-green-50 text-green-700 border-green-200' },
  ok_parcial: { label: 'OK Parcial', color: 'bg-lime-50 text-lime-700 border-lime-200' },
  error: { label: 'ERROR', color: 'bg-red-50 text-red-700 border-red-200' },
  diferencia: { label: 'DIFERENCIA', color: 'bg-orange-50 text-orange-700 border-orange-200' },
  no_verificable: { label: 'NO VERIFICABLE', color: 'bg-slate-100 text-slate-600 border-slate-200' },
  falta_doc: { label: 'FALTA DOC', color: 'bg-amber-50 text-amber-700 border-amber-200' },
  criterio: { label: 'CRITERIO', color: 'bg-blue-50 text-blue-700 border-blue-200' },
  aviso: { label: 'AVISO', color: 'bg-yellow-50 text-yellow-700 border-yellow-200' },
  opcion: { label: 'OPCIÓN', color: 'bg-purple-50 text-purple-700 border-purple-200' },
  riesgo: { label: 'RIESGO', color: 'bg-orange-50 text-orange-700 border-orange-200' },
  bloquea: { label: 'BLOQUEA', color: 'bg-red-100 text-red-800 border-red-300' },
};

const PRIORITY_LABELS = {
  bloquea: { label: 'BLOQUEA', color: 'bg-red-600 text-white' },
  alta: { label: 'ALTA', color: 'bg-orange-500 text-white' },
  media: { label: 'MEDIA', color: 'bg-amber-400 text-amber-900' },
  baja: { label: 'BAJA', color: 'bg-slate-300 text-slate-700' },
  posterior: { label: 'POSTERIOR', color: 'bg-blue-300 text-blue-800' },
  ccaa: { label: 'CCAA', color: 'bg-indigo-300 text-indigo-800' },
  menor: { label: 'MENOR', color: 'bg-slate-200 text-slate-600' },
};

const FILE_STATUS_COLORS = {
  subido: 'bg-blue-50 text-blue-700',
  procesando: 'bg-amber-50 text-amber-700',
  ocr_pendiente: 'bg-orange-50 text-orange-700',
  ocr_procesado: 'bg-teal-50 text-teal-700',
  extraido: 'bg-indigo-50 text-indigo-700',
  clasificado: 'bg-green-50 text-green-700',
  con_error: 'bg-red-50 text-red-700',
  duplicado_posible: 'bg-purple-50 text-purple-700',
  requiere_revision_manual: 'bg-yellow-50 text-yellow-700',
  excluido_admin: 'bg-slate-100 text-slate-500',
};

export default function AuditCaseDetail({ caseId, onBack }) {
  const queryClient = useQueryClient();
  const [uploading, setUploading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [generatingReport, setGeneratingReport] = useState(false);
  const [reportType, setReportType] = useState('informe_completo');
  const [expandedFindings, setExpandedFindings] = useState({});

  const { data: auditCase, isLoading } = useQuery({
    queryKey: ['auditCase', caseId],
    queryFn: () => base44.entities.TaxeaAuditCase.get(caseId),
    enabled: !!caseId,
  });

  const { data: files = [], refetch: refetchFiles } = useQuery({
    queryKey: ['auditFiles', caseId],
    queryFn: () => base44.entities.TaxeaAuditFile.filter({ auditCaseId: caseId }),
    enabled: !!caseId,
  });

  const { data: findings = [] } = useQuery({
    queryKey: ['auditFindings', caseId],
    queryFn: () => base44.entities.TaxeaAuditFinding.filter({ auditCaseId: caseId }),
    enabled: !!caseId,
  });

  const { data: reports = [] } = useQuery({
    queryKey: ['auditReports', caseId],
    queryFn: () => base44.entities.TaxeaAuditReport.filter({ auditCaseId: caseId }, '-version'),
    enabled: !!caseId,
  });

  const handleUpload = async (e) => {
    const fileList = Array.from(e.target.files);
    if (fileList.length === 0) return;
    setUploading(true);
    try {
      for (const file of fileList) {
        const { file_url } = await uploadRelatedDocument({file,contextKind:'audit',contextId:caseId});
        const ext = file.name.split('.').pop().toLowerCase();
        const mimeMap = { pdf: 'application/pdf', jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', xlsx: 'application/vnd.openxmlformats', xls: 'application/vnd.ms-excel', csv: 'text/csv', docx: 'application/vnd.openxmlformats', txt: 'text/plain', xml: 'application/xml', zip: 'application/zip' };
        await base44.entities.TaxeaAuditFile.create({
          auditCaseId: caseId,
          originalName: file.name,
          storagePath: file_url,
          mimeType: mimeMap[ext] || file.type || 'application/octet-stream',
          extension: ext,
          size: file.size,
          uploadStatus: 'subido',
          requiresOcr: ['jpg', 'jpeg', 'png'].includes(ext),
          hasTextLayer: ext === 'pdf'
        });
      }
      toast.success(`${fileList.length} archivo(s) subido(s)`);
      await base44.entities.TaxeaAuditCase.update(caseId, { status: 'documentos_subidos' });
      refetchFiles();
      queryClient.invalidateQueries({ queryKey: ['auditCase', caseId] });
    } catch (err) {
      toast.error('Error subiendo archivos: ' + err.message);
    }
    setUploading(false);
    e.target.value = '';
  };

  const handleAnalyze = async () => {
    setAnalyzing(true);
    try {
      const res = await base44.functions.invoke('runAuditAnalysis', { auditCaseId: caseId });
      const data = res.data || res;
      if (data.error) {
        toast.error(data.error);
      } else {
        toast.success(`Análisis completado: ${data.findingsCreated} hallazgos, riesgo ${data.riskLevel}`);
        queryClient.invalidateQueries({ queryKey: ['auditCase', caseId] });
        queryClient.invalidateQueries({ queryKey: ['auditFiles', caseId] });
        queryClient.invalidateQueries({ queryKey: ['auditFindings', caseId] });
      }
    } catch (err) {
      toast.error('Error en análisis: ' + err.message);
    }
    setAnalyzing(false);
  };

  const handleGenerateReport = async () => {
    setGeneratingReport(true);
    try {
      const res = await base44.functions.invoke('generateAuditReport', { auditCaseId: caseId, reportType });
      const data = res.data || res;
      if (data.error) {
        toast.error(data.error);
      } else {
        toast.success(`Informe v${data.version} generado`);
        queryClient.invalidateQueries({ queryKey: ['auditReports', caseId] });
        queryClient.invalidateQueries({ queryKey: ['auditCase', caseId] });
      }
    } catch (err) {
      toast.error('Error generando informe: ' + err.message);
    }
    setGeneratingReport(false);
  };

  const updateFindingStatus = async (findingId, newStatus) => {
    try {
      await base44.entities.TaxeaAuditFinding.update(findingId, { status: newStatus });
      queryClient.invalidateQueries({ queryKey: ['auditFindings', caseId] });
      toast.success('Hallazgo actualizado');
    } catch (err) {
      toast.error('Error: ' + err.message);
    }
  };

  const downloadReport = (report) => {
    const blob = new Blob([report.markdownContent], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${report.title}.md`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportPDF = async (report) => {
    try {
      await exportReportToPDF(report);
      toast.success('PDF exportado');
    } catch (err) {
      toast.error('Error exportando PDF: ' + err.message);
    }
  };

  if (isLoading || !auditCase) {
    return <div className="p-12 text-center"><Loader2 className="w-6 h-6 text-teal animate-spin mx-auto" /></div>;
  }

  const bloqueos = findings.filter(f => f.priority === 'bloquea' || f.verdict === 'bloquea').length;
  const errores = findings.filter(f => f.verdict === 'error').length;
  const riesgos = findings.filter(f => f.verdict === 'riesgo').length;
  const noVerif = findings.filter(f => ['no_verificable', 'falta_doc'].includes(f.verdict)).length;

  return (
    <div>
      <div className="flex items-center gap-3 mb-4">
        <Button variant="ghost" size="icon" onClick={onBack} className="h-8 w-8">
          <ArrowLeft className="w-4 h-4" />
        </Button>
        <div className="flex-1 min-w-0">
          <h1 className="text-xl font-jakarta font-bold text-foreground truncate">{auditCase.title}</h1>
          <p className="text-sm text-muted-foreground">
            {auditCase.clientName || 'Sin cliente'} · {auditCase.clientNif || 'N/A'} · Ej. {auditCase.taxYear}
          </p>
        </div>
        <Badge variant="outline" className={`capitalize ${auditCase.riskLevel === 'critico' ? 'border-red-300 text-red-700' : auditCase.riskLevel === 'alto' ? 'border-orange-300 text-orange-700' : ''}`}>
          Riesgo: {auditCase.riskLevel}
        </Badge>
      </div>

      {/* Tarjetas iniciales */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-4">
        <div className={`rounded-xl border p-3 ${auditCase.recommendation === 'no_presentar' ? 'bg-red-50 border-red-200' : auditCase.recommendation === 'parar_24_48h' ? 'bg-orange-50 border-orange-200' : auditCase.recommendation === 'pendiente_documentacion' ? 'bg-amber-50 border-amber-200' : 'bg-green-50 border-green-200'}`}>
          <p className="text-[10px] text-muted-foreground uppercase tracking-wide">Recomendación</p>
          <p className="text-sm font-bold mt-0.5">
            {auditCase.recommendation === 'ok_continuar' ? 'OK para continuar' :
             auditCase.recommendation === 'revisar_antes_cerrar' ? 'Revisar antes de cerrar' :
             auditCase.recommendation === 'parar_24_48h' ? 'Parar 24-48h' :
             auditCase.recommendation === 'no_presentar' ? 'No presentar' :
             auditCase.recommendation === 'pendiente_documentacion' ? 'Pendiente documentación' :
             'Solo borrador'}
          </p>
        </div>
        <div className="bg-card rounded-xl border border-border p-3">
          <p className="text-[10px] text-muted-foreground uppercase tracking-wide">Impacto estimado</p>
          <p className="text-xs font-medium mt-0.5 text-foreground">{auditCase.impactEstimated || 'Sin cuantificar'}</p>
        </div>
        <div className={`rounded-xl border p-3 ${auditCase.riskLevel === 'critico' ? 'bg-red-50 border-red-200' : auditCase.riskLevel === 'alto' ? 'bg-orange-50 border-orange-200' : auditCase.riskLevel === 'medio' ? 'bg-amber-50 border-amber-200' : 'bg-green-50 border-green-200'}`}>
          <p className="text-[10px] text-muted-foreground uppercase tracking-wide">Riesgo</p>
          <p className="text-sm font-bold mt-0.5 capitalize">{auditCase.riskLevel}</p>
        </div>
        <div className="bg-card rounded-xl border border-border p-3">
          <p className="text-[10px] text-muted-foreground uppercase tracking-wide">Estado</p>
          <p className="text-sm font-bold mt-0.5 capitalize">{auditCase.status.replace(/_/g, ' ')}</p>
        </div>
      </div>

      {/* KPI cards */}
      <div className="grid grid-cols-2 lg:grid-cols-5 gap-3 mb-4">
        <div className="bg-card rounded-lg border border-border p-3">
          <p className="text-[10px] text-muted-foreground uppercase tracking-wide">Documentos</p>
          <p className="text-xl font-bold text-foreground">{files.length}</p>
        </div>
        <div className="bg-card rounded-lg border border-border p-3">
          <p className="text-[10px] text-muted-foreground uppercase tracking-wide">Hallazgos</p>
          <p className="text-xl font-bold text-foreground">{findings.length}</p>
        </div>
        <div className="bg-red-50 border border-red-200 rounded-lg p-3">
          <p className="text-[10px] text-red-600 uppercase tracking-wide">Bloqueos</p>
          <p className="text-xl font-bold text-red-700">{bloqueos}</p>
        </div>
        <div className="bg-orange-50 border border-orange-200 rounded-lg p-3">
          <p className="text-[10px] text-orange-600 uppercase tracking-wide">Errores/Riesgos</p>
          <p className="text-xl font-bold text-orange-700">{errores + riesgos}</p>
        </div>
        <div className="bg-slate-50 border border-slate-200 rounded-lg p-3">
          <p className="text-[10px] text-slate-500 uppercase tracking-wide">No verificable</p>
          <p className="text-xl font-bold text-slate-600">{noVerif}</p>
        </div>
      </div>

      {/* Action buttons */}
      <div className="flex flex-wrap items-center gap-2 mb-4">
        <label className="cursor-pointer">
          <input type="file" multiple className="hidden" onChange={handleUpload} accept=".pdf,.jpg,.jpeg,.png,.xlsx,.xls,.csv,.docx,.txt,.xml,.zip" />
          <span className="inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80 h-9 px-4 py-2">
            {uploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
            Subir documentos
          </span>
        </label>
        <Button onClick={handleAnalyze} disabled={analyzing || files.length === 0} className="bg-teal hover:bg-teal-dark h-9">
          {analyzing ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : <Play className="w-4 h-4 mr-1.5" />}
          {analyzing ? 'Analizando...' : 'Ejecutar análisis'}
        </Button>
        <div className="flex items-center gap-2">
          <Select value={reportType} onValueChange={setReportType}>
            <SelectTrigger className="w-48 h-9"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="informe_completo">Informe completo</SelectItem>
              <SelectItem value="resumen_ejecutivo">Resumen ejecutivo</SelectItem>
              <SelectItem value="solo_bloqueos">Solo bloqueos</SelectItem>
              <SelectItem value="informe_gestoria">Informe para gestoría</SelectItem>
              <SelectItem value="informe_cliente">Informe para cliente</SelectItem>
              <SelectItem value="anexo_juridico">Anexo jurídico</SelectItem>
              <SelectItem value="inventario_documental">Inventario documental</SelectItem>
            </SelectContent>
          </Select>
          <Button onClick={handleGenerateReport} disabled={generatingReport || findings.length === 0} variant="outline" className="h-9">
            {generatingReport ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : <FileCheck className="w-4 h-4 mr-1.5" />}
            Generar informe
          </Button>
        </div>
      </div>

      {auditCase.summaryMarkdown && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 mb-4">
          <p className="text-xs font-semibold text-amber-700 mb-2 flex items-center gap-1.5">
            <AlertTriangle className="w-3.5 h-3.5" /> Resumen ejecutivo del análisis
          </p>
          <div className="prose prose-sm max-w-none text-amber-900">
            <ReactMarkdown>{auditCase.summaryMarkdown}</ReactMarkdown>
          </div>
        </div>
      )}

      <Tabs defaultValue="documentos" className="w-full">
        <TabsList className="flex-wrap">
          <TabsTrigger value="documentos">Documentos ({files.length})</TabsTrigger>
          <TabsTrigger value="hallazgos">Hallazgos ({findings.length})</TabsTrigger>
          <TabsTrigger value="investigacion">Investigación</TabsTrigger>
          <TabsTrigger value="informe">Informe ({reports.length})</TabsTrigger>
          <TabsTrigger value="email">Email</TabsTrigger>
          <TabsTrigger value="historial">Historial</TabsTrigger>
        </TabsList>

        {/* Documentos */}
        <TabsContent value="documentos" className="mt-4">
          <div className="bg-card rounded-xl border border-border shadow-card">
            {files.length === 0 ? (
              <div className="p-8 text-center">
                <FileText className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-40" />
                <p className="text-sm text-muted-foreground">Sin documentos. Sube archivos para comenzar el análisis.</p>
              </div>
            ) : (
              <div className="divide-y divide-border">
                {files.map((f, i) => (
                  <div key={f.id} className="px-4 py-3 flex items-center gap-3">
                    <span className="text-xs text-muted-foreground font-mono w-6">{i + 1}.</span>
                    <FileText className="w-4 h-4 text-slate-400 flex-shrink-0" />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-foreground truncate">{f.originalName}</p>
                      <p className="text-xs text-muted-foreground truncate">
                        {f.documentType || 'Sin clasificar'} · {f.whatItAccredits || 'Sin acreditar'}
                        {f.pageCount ? ` · ${f.pageCount} pág.` : ''}
                        {f.requiresOcr ? ' · Requiere OCR' : ''}
                      </p>
                    </div>
                    <span className={`text-[10px] px-2 py-0.5 rounded font-medium ${FILE_STATUS_COLORS[f.uploadStatus] || 'bg-slate-100 text-slate-600'}`}>
                      {f.uploadStatus}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </TabsContent>

        {/* Hallazgos */}
        <TabsContent value="hallazgos" className="mt-4">
          {findings.length === 0 ? (
            <div className="bg-card rounded-xl border border-border shadow-card p-8 text-center">
              <Shield className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-40" />
              <p className="text-sm text-muted-foreground">Sin hallazgos. Ejecuta el análisis para detectarlos.</p>
            </div>
          ) : (
            <div className="space-y-2">
              {findings.map(f => {
                const verdict = VERDICT_LABELS[f.verdict] || VERDICT_LABELS.no_verificable;
                const priority = PRIORITY_LABELS[f.priority] || PRIORITY_LABELS.media;
                const isExpanded = expandedFindings[f.id];
                return (
                  <div key={f.id} className="bg-card rounded-xl border border-border shadow-card overflow-hidden">
                    <div className="px-4 py-3 cursor-pointer" onClick={() => setExpandedFindings(s => ({ ...s, [f.id]: !s[f.id] }))}>
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="text-xs font-mono font-bold text-slate-500">{f.findingCode}</span>
                        <span className="text-sm font-medium text-foreground flex-1">{f.title}</span>
                        <span className={`text-[10px] px-2 py-0.5 rounded border font-bold ${verdict.color}`}>{verdict.label}</span>
                        <span className={`text-[10px] px-2 py-0.5 rounded font-bold ${priority.color}`}>{priority.label}</span>
                        {isExpanded ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
                      </div>
                    </div>
                    {isExpanded && (
                      <div className="px-4 pb-4 space-y-2 border-t border-border bg-slate-50/50">
                        {f.documentClaim && <div><p className="text-[10px] uppercase text-muted-foreground font-semibold">Documento afirma</p><p className="text-sm">{f.documentClaim}</p></div>}
                        {f.verification && <div><p className="text-[10px] uppercase text-muted-foreground font-semibold">Verificado</p><p className="text-sm">{f.verification}</p></div>}
                        {f.exactEvidence && <div><p className="text-[10px] uppercase text-muted-foreground font-semibold">Evidencia exacta</p><p className="text-sm font-mono bg-amber-50 border border-amber-100 rounded p-2">{f.exactEvidence}</p></div>}
                        {f.economicEffect && <div><p className="text-[10px] uppercase text-muted-foreground font-semibold">Efecto económico</p><p className="text-sm">{f.economicEffect}</p></div>}
                        {f.actionRecommended && <div><p className="text-[10px] uppercase text-muted-foreground font-semibold">Acción recomendada</p><p className="text-sm">{f.actionRecommended}</p></div>}
                        <div className="flex items-center gap-2 pt-2">
                          <span className="text-[10px] uppercase text-muted-foreground font-semibold">Estado:</span>
                          <Select value={f.status} onValueChange={(v) => updateFindingStatus(f.id, v)}>
                            <SelectTrigger className="w-40 h-7 text-xs"><SelectValue /></SelectTrigger>
                            <SelectContent>
                              <SelectItem value="detectado">Detectado</SelectItem>
                              <SelectItem value="en_revision">En revisión</SelectItem>
                              <SelectItem value="aceptado">Aceptado</SelectItem>
                              <SelectItem value="descartado">Descartado</SelectItem>
                              <SelectItem value="excluido_informe">Excluido informe</SelectItem>
                              <SelectItem value="resuelto">Resuelto</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </TabsContent>

        {/* Investigación jurídica */}
        <TabsContent value="investigacion" className="mt-4">
          <AuditInvestigationTab caseId={caseId} />
        </TabsContent>

        {/* Informe */}
        <TabsContent value="informe" className="mt-4">
          {reports.length === 0 ? (
            <div className="bg-card rounded-xl border border-border shadow-card p-8 text-center">
              <FileCheck className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-40" />
              <p className="text-sm text-muted-foreground">Sin informes generados. Ejecuta el análisis primero y luego genera el informe.</p>
            </div>
          ) : (
            <div className="space-y-4">
              {reports.map(r => (
                <div key={r.id} className="bg-card rounded-xl border border-border shadow-card">
                  <div className="flex items-center justify-between px-4 py-3 border-b border-border">
                    <div>
                      <p className="font-medium text-foreground">{r.title}</p>
                      <p className="text-xs text-muted-foreground">v{r.version} · {r.reportType} · {r.generatedBy}</p>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <Button variant="outline" size="sm" onClick={() => downloadReport(r)} className="h-8">
                        <Download className="w-3.5 h-3.5 mr-1.5" /> MD
                      </Button>
                      <Button variant="outline" size="sm" onClick={() => handleExportPDF(r)} className="h-8">
                        <Download className="w-3.5 h-3.5 mr-1.5" /> PDF
                      </Button>
                      <Button variant="outline" size="sm" onClick={() => exportReportToDOCX(r)} className="h-8">
                        <Download className="w-3.5 h-3.5 mr-1.5" /> DOCX
                      </Button>
                    </div>
                  </div>
                  <div className="p-4 prose prose-sm max-w-none">
                    <ReactMarkdown>{r.markdownContent}</ReactMarkdown>
                  </div>
                </div>
              ))}
            </div>
          )}
        </TabsContent>
        {/* Email */}
        <TabsContent value="email" className="mt-4">
          <AuditEmailTab caseId={caseId} />
        </TabsContent>

        {/* Historial */}
        <TabsContent value="historial" className="mt-4">
          <AuditHistoryTab caseId={caseId} />
        </TabsContent>
      </Tabs>

      <div className="mt-6 p-3 bg-slate-50 border border-slate-200 rounded-lg">
        <p className="text-xs text-slate-500 flex items-center gap-1.5">
          <Lock className="w-3 h-3" />
          Borrador pendiente de revisión profesional. No sustituye asesoramiento fiscal, contable ni jurídico. Basado exclusivamente en la documentación aportada.
        </p>
      </div>
    </div>
  );
}

src/components/mercantil/MercantilCuenta:
import { uploadRelatedDocument } from '@/lib/privateDocuments';
import { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Plus, Upload, ExternalLink } from 'lucide-react';
import { cn } from '@/lib/utils';

const TIPOS_DOC = [
  { value: 'archivo_d2', label: 'Archivo D2 presentado' },
  { value: 'justificante_presentacion', label: 'Justificante de presentación' },
  { value: 'justificante_inscripcion', label: 'Justificante de inscripción' },
  { value: 'balance', label: 'Balance cerrado' },
  { value: 'pyg', label: 'Cuenta de PyG cerrada' },
  { value: 'memoria', label: 'Memoria presentada al RM' },
  { value: 'certificacion_acta', label: 'Certificación del acta' },
  { value: 'acta_aprobacion', label: 'Acta de aprobación de cuentas' },
  { value: 'informe_auditoria', label: 'Informe de auditoría' },
  { value: 'informe_gestion', label: 'Informe de gestión' },
  { value: 'subsanacion', label: 'Documento de subsanación' },
  { value: 'otro', label: 'Otro documento' },
];

const ESTADO_DOC = {
  pendiente: 'bg-slate-100 text-slate-600',
  subido:    'bg-blue-100 text-blue-700',
  revisado:  'bg-indigo-100 text-indigo-700',
  presentado:'bg-amber-100 text-amber-700',
  aceptado:  'bg-emerald-100 text-emerald-700',
  sustituido:'bg-slate-100 text-slate-400 line-through',
};

const ESTADOS_CUENTAS = [
  { value: 'pendiente', label: 'Contabilidad cerrada — pendiente de revisión' },
  { value: 'en_preparacion', label: 'Balance y PyG revisados' },
  { value: 'presentado', label: 'Presentado en Registro Mercantil' },
  { value: 'inscrito', label: 'Inscrito correctamente' },
  { value: 'con_defectos', label: 'Con defectos o subsanación' },
  { value: 'cerrado', label: 'Cerrado' },
];

export default function MercantilCuentasTab({ expediente, user, onRefresh }) {
  const [docs, setDocs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [newDoc, setNewDoc] = useState({ tipoDocumento: 'archivo_d2', nombre: '', fechaDocumento: '', comentarios: '' });
  const [uploading, setUploading] = useState(false);
  const [depositoData, setDepositoData] = useState({
    fechaPresentacion: expediente.fechaPresentacionCuentas || '',
    numPresentacion: expediente.numPresentacionCuentas || '',
    fechaInscripcion: expediente.fechaInscripcionCuentas || '',
    resultado: expediente.resultadoCuentas || '',
    observaciones: '',
  });
  const [savingDeposito, setSavingDeposito] = useState(false);

  const load = async () => {
    setLoading(true);
    const data = await base44.entities.MercantilDocumento.filter(
      { expedienteId: expediente.id, carpeta: '02_cuentas_anuales' }, '-created_date', 100
    ).catch(() => []);
    setDocs(data || []);
    setLoading(false);
  };

  useEffect(() => { if (expediente) load(); }, [expediente.id]);

  const addDoc = async (fileUrl) => {
    const tipoLabel = TIPOS_DOC.find(t => t.value === newDoc.tipoDocumento)?.label || newDoc.nombre;
    await base44.entities.MercantilDocumento.create({
      expedienteId: expediente.id,
      sociedadId: expediente.sociedadId,
      carpeta: '02_cuentas_anuales',
      tipoDocumento: newDoc.tipoDocumento,
      nombre: newDoc.nombre || tipoLabel,
      estado: 'subido',
      fechaDocumento: newDoc.fechaDocumento,
      fechaSubida: new Date().toISOString(),
      subidoPor: user?.email || 'admin',
      version: 1,
      fileUrl,
      comentarios: newDoc.comentarios,
      esBorrador: false,
    });
    await base44.entities.MercantilHistorial.create({
      expedienteId: expediente.id, sociedadId: expediente.sociedadId,
      fecha: new Date().toISOString(), usuario: user?.email || 'admin',
      accion: `Documento subido: ${newDoc.nombre || tipoLabel}`,
      tipoAccion: 'documento_subido',
    });
    load();
    setShowAdd(false);
    setNewDoc({ tipoDocumento: 'archivo_d2', nombre: '', fechaDocumento: '', comentarios: '' });
  };

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    const { file_url } = await uploadRelatedDocument({file,contextKind:'mercantil',contextId:expediente.sociedadId});
    await addDoc(file_url);
    setUploading(false);
  };

  const updateEstado = async (doc, estado) => {
    await base44.entities.MercantilDocumento.update(doc.id, { estado });
    setDocs(prev => prev.map(d => d.id === doc.id ? { ...d, estado } : d));
  };

  const saveDeposito = async () => {
    setSavingDeposito(true);
    await base44.entities.MercantilExpediente.update(expediente.id, {
      fechaPresentacionCuentas: depositoData.fechaPresentacion,
      numPresentacionCuentas: depositoData.numPresentacion,
      fechaInscripcionCuentas: depositoData.fechaInscripcion,
      resultadoCuentas: depositoData.resultado,
      ultimaActualizacion: new Date().toISOString(),
    });
    setSavingDeposito(false);
    onRefresh?.();
  };

  if (loading) return <div className="p-8 text-center"><div className="w-5 h-5 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" /></div>;

  return (
    <div className="space-y-5">
      {/* Estado cuentas */}
      <div className="bg-card border border-border rounded-xl p-4 space-y-3">
        <h3 className="text-sm font-semibold text-foreground">Estado de cuentas anuales</h3>
        <Select value={expediente.estadoCuentas || 'pendiente'} onValueChange={async v => {
          await base44.entities.MercantilExpediente.update(expediente.id, { estadoCuentas: v, ultimaActualizacion: new Date().toISOString() });
          onRefresh?.();
        }}>
          <SelectTrigger className="h-8 text-xs max-w-md"><SelectValue /></SelectTrigger>
          <SelectContent>
            {ESTADOS_CUENTAS.map(e => <SelectItem key={e.value} value={e.value} className="text-xs">{e.label}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {/* Documentos */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        <div className="flex items-center justify-between px-4 py-3 border-b border-border bg-secondary/30">
          <div>
            <h3 className="text-sm font-semibold text-foreground">Documentos de cuentas anuales</h3>
            <p className="text-xs text-muted-foreground">Archivo D2, balances, memoria, actas, inscripciones...</p>
          </div>
          <Button size="sm" onClick={() => setShowAdd(!showAdd)} className="h-7 gap-1.5 text-xs"><Plus className="w-3 h-3" />Añadir</Button>
        </div>

        {showAdd && (
          <div className="bg-blue-50/50 border-b border-border p-4 space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-xs text-muted-foreground">Tipo de documento</label>
                <Select value={newDoc.tipoDocumento} onValueChange={v => setNewDoc(p => ({ ...p, tipoDocumento: v }))}>
                  <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {TIPOS_DOC.map(t => <SelectItem key={t.value} value={t.value} className="text-xs">{t.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <label className="text-xs text-muted-foreground">Nombre / descripción</label>
                <Input value={newDoc.nombre} onChange={e => setNewDoc(p => ({ ...p, nombre: e.target.value }))} className="h-8 text-xs" placeholder="Descripción opcional" />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-muted-foreground">Fecha del documento</label>
                <Input type="date" value={newDoc.fechaDocumento} onChange={e => setNewDoc(p => ({ ...p, fechaDocumento: e.target.value }))} className="h-8 text-xs" />
              </div>
              <div className="space-y-1">
                <label className="text-xs text-muted-foreground">Comentarios</label>
                <Input value={newDoc.comentarios} onChange={e => setNewDoc(p => ({ ...p, comentarios: e.target.value }))} className="h-8 text-xs" placeholder="Nota interna..." />
              </div>
            </div>
            <label className="cursor-pointer">
              <div className="flex items-center gap-2 border-2 border-dashed border-border rounded-lg px-4 py-3 hover:bg-secondary/20 transition-colors">
                <Upload className="w-4 h-4 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">{uploading ? 'Subiendo...' : 'Selecciona o arrastra el archivo aquí'}</span>
              </div>
              <input type="file" className="hidden" onChange={handleUpload} disabled={uploading} />
            </label>
          </div>
        )}

        {docs.length === 0 ? (
          <p className="px-4 py-8 text-center text-sm text-muted-foreground">Sin documentos. Añade el archivo D2 u otros documentos de cuentas anuales.</p>
        ) : (
          <div className="divide-y divide-border">
            {docs.map(doc => (
              <div key={doc.id} className={cn('flex items-center gap-3 px-4 py-3 text-sm', doc.estado === 'sustituido' && 'opacity-50')}>
                <div className="flex-1 min-w-0">
                  <p className={cn('font-medium text-foreground', doc.estado === 'sustituido' && 'line-through')}>{doc.nombre}</p>
                  <p className="text-[11px] text-muted-foreground">
                    {TIPOS_DOC.find(t => t.value === doc.tipoDocumento)?.label || doc.tipoDocumento}
                    {doc.fechaDocumento && ` · ${new Date(doc.fechaDocumento).toLocaleDateString('es-ES')}`}
                    {doc.subidoPor && ` · ${doc.subidoPor}`}
                    {doc.comentarios && ` · ${doc.comentarios}`}
                  </p>
                </div>
                <span className={cn('text-[10px] font-semibold px-1.5 py-0.5 rounded capitalize', ESTADO_DOC[doc.estado])}>{doc.estado}</span>
                <Select value={doc.estado} onValueChange={v => updateEstado(doc, v)}>
                  <SelectTrigger className="h-7 w-28 text-[10px]"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {Object.keys(ESTADO_DOC).map(k => <SelectItem key={k} value={k} className="text-xs capitalize">{k}</SelectItem>)}
                  </SelectContent>
                </Select>
                {doc.fileUrl && (
                  <a href={doc.fileUrl} target="_blank" rel="noopener noreferrer" className="text-primary hover:text-primary/80">
                    <ExternalLink className="w-4 h-4" />
                  </a>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Resultado depósito */}
      <div className="bg-card border border-border rounded-xl p-5 space-y-4">
        <div>
          <h3 className="text-sm font-semibold text-foreground">Resultado del depósito de cuentas</h3>
          <p className="text-xs text-muted-foreground">Fecha de presentación, inscripción y resultado en el Registro Mercantil.</p>
        </div>
        <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
          {[
            { label: 'Fecha de presentación', key: 'fechaPresentacion', type: 'date' },
            { label: 'Nº / Ref. de entrada', key: 'numPresentacion' },
            { label: 'Fecha de inscripción', key: 'fechaInscripcion', type: 'date' },
          ].map(f => (
            <div key={f.key} className="space-y-1">
              <label className="text-xs text-muted-foreground">{f.label}</label>
              <Input type={f.type || 'text'} value={depositoData[f.key] || ''} onChange={e => setDepositoData(p => ({ ...p, [f.key]: e.target.value }))} className="h-8 text-xs" />
            </div>
          ))}
          <div className="space-y-1">
            <label className="text-xs text-muted-foreground">Resultado</label>
            <Select value={depositoData.resultado} onValueChange={v => setDepositoData(p => ({ ...p, resultado: v }))}>
              <SelectTrigger className="h-8 text-xs"><SelectValue placeholder="Seleccionar..." /></SelectTrigger>
              <SelectContent>
                <SelectItem value="pendiente">Pendiente</SelectItem>
                <SelectItem value="inscrito">Inscrito correctamente</SelectItem>
                <SelectItem value="con_defectos">Con defectos</SelectItem>
                <SelectItem value="subsanado">Subsanado</SelectItem>
                <SelectItem value="rechazado">Rechazado</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
        <div className="flex justify-end">
          <Button size="sm" onClick={saveDeposito} disabled={savingDeposito}>{savingDeposito ? 'Guardando...' : 'Guardar resultado'}</Button>
        </div>
      </div>
    </div>
  );
}

src/components/mercantil/MercantilDocume:
import { uploadRelatedDocument } from '@/lib/privateDocuments';
import { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Upload, Search, FileText, ExternalLink, Tag } from 'lucide-react';
import { cn } from '@/lib/utils';

const CARPETAS = [
  { value: '01_libros', label: '01 Legalización de libros' },
  { value: '02_cuentas_anuales', label: '02 Cuentas anuales' },
  { value: '03_justificantes_rm', label: '03 Justificantes Registro Mercantil' },
  { value: '04_subsanaciones', label: '04 Subsanaciones' },
  { value: '05_documentacion_final', label: '05 Documentación final cerrada' },
];

const ETIQUETAS = ['A3','Legalia','D2','Registro Mercantil','Balance','PyG','Memoria','Actas','Socios','Subsanación'];

const ESTADO_COLORS = {
  pendiente: 'text-slate-500 bg-slate-50 border-slate-200',
  subido: 'text-blue-700 bg-blue-50 border-blue-200',
  revisado: 'text-indigo-700 bg-indigo-50 border-indigo-200',
  presentado: 'text-amber-700 bg-amber-50 border-amber-200',
  aceptado: 'text-emerald-700 bg-emerald-50 border-emerald-200',
  sustituido: 'text-slate-400 bg-slate-50 border-slate-100',
};

const fmtDate = d => d ? new Date(d).toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: '2-digit' }) : '—';

export default function MercantilDocumentalTab({ expediente, user, isAdmin }) {
  const [docs, setDocs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterCarpeta, setFilterCarpeta] = useState('all');
  const [filterEstado, setFilterEstado] = useState('all');
  const [uploading, setUploading] = useState(false);
  const [uploadForm, setUploadForm] = useState({ carpeta: '03_justificantes_rm', nombre: '', etiquetas: [], comentarios: '' });
  const [showUpload, setShowUpload] = useState(false);

  const load = async () => {
    setLoading(true);
    const data = await base44.entities.MercantilDocumento.filter({ expedienteId: expediente.id }, '-created_date', 200).catch(() => []);
    setDocs(data || []);
    setLoading(false);
  };

  useEffect(() => { if (expediente) load(); }, [expediente.id]);

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    const { file_url } = await uploadRelatedDocument({file,contextKind:'mercantil',contextId:expediente.sociedadId});
    await base44.entities.MercantilDocumento.create({
      expedienteId: expediente.id,
      sociedadId: expediente.sociedadId,
      carpeta: uploadForm.carpeta,
      nombre: uploadForm.nombre || file.name,
      estado: 'subido',
      fechaSubida: new Date().toISOString(),
      subidoPor: user?.email || 'admin',
      version: 1,
      fileUrl: file_url,
      etiquetas: uploadForm.etiquetas,
      comentarios: uploadForm.comentarios,
      tipoDocumento: 'otro',
    });
    await base44.entities.MercantilHistorial.create({
      expedienteId: expediente.id, sociedadId: expediente.sociedadId,
      fecha: new Date().toISOString(), usuario: user?.email || 'admin',
      accion: `Documento subido al gestor: ${uploadForm.nombre || file.name}`,
      tipoAccion: 'documento_subido',
    });
    setUploading(false);
    setShowUpload(false);
    setUploadForm({ carpeta: '03_justificantes_rm', nombre: '', etiquetas: [], comentarios: '' });
    load();
  };

  const toggleEtiqueta = (tag) => {
    setUploadForm(p => ({
      ...p,
      etiquetas: p.etiquetas.includes(tag) ? p.etiquetas.filter(t => t !== tag) : [...p.etiquetas, tag]
    }));
  };

  const updateEstado = async (doc, estado) => {
    if (estado === 'sustituido' && !isAdmin) { alert('Solo un administrador puede marcar un documento como sustituido.'); return; }
    await base44.entities.MercantilDocumento.update(doc.id, { estado });
    setDocs(prev => prev.map(d => d.id === doc.id ? { ...d, estado } : d));
  };

  const filtered = docs.filter(d => {
    const matchSearch = !search || d.nombre?.toLowerCase().includes(search.toLowerCase()) || (d.etiquetas || []).some(t => t.toLowerCase().includes(search.toLowerCase()));
    const matchCarpeta = filterCarpeta === 'all' || d.carpeta === filterCarpeta;
    const matchEstado = filterEstado === 'all' || d.estado === filterEstado;
    return matchSearch && matchCarpeta && matchEstado;
  });

  // Group by carpeta
  const grouped = {};
  filtered.forEach(d => {
    const c = d.carpeta || '05_documentacion_final';
    if (!grouped[c]) grouped[c] = [];
    grouped[c].push(d);
  });

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h3 className="text-sm font-semibold text-foreground">Gestor documental</h3>
          <p className="text-xs text-muted-foreground">Archivo completo por carpeta. Control de versiones y estado.</p>
        </div>
        <Button size="sm" onClick={() => setShowUpload(!showUpload)} className="h-8 gap-1.5"><Upload className="w-3.5 h-3.5" />Subir documento</Button>
      </div>

      {showUpload && (
        <div className="bg-secondary/20 border border-border rounded-xl p-4 space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className="text-xs text-muted-foreground">Carpeta destino</label>
              <Select value={uploadForm.carpeta} onValueChange={v => setUploadForm(p => ({ ...p, carpeta: v }))}>
                <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {CARPETAS.map(c => <SelectItem key={c.value} value={c.value} className="text-xs">{c.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <label className="text-xs text-muted-foreground">Nombre del documento</label>
              <Input value={uploadForm.nombre} onChange={e => setUploadForm(p => ({ ...p, nombre: e.target.value }))} className="h-8 text-xs" placeholder="Nombre descriptivo (opcional)" />
            </div>
            <div className="col-span-2 space-y-1">
              <label className="text-xs text-muted-foreground">Etiquetas</label>
              <div className="flex flex-wrap gap-1.5">
                {ETIQUETAS.map(tag => (
                  <button key={tag} onClick={() => toggleEtiqueta(tag)}
                    className={cn('text-[10px] px-2 py-0.5 rounded-full border transition-colors', uploadForm.etiquetas.includes(tag) ? 'bg-primary text-primary-foreground border-primary' : 'border-border text-muted-foreground hover:border-primary/50')}>
                    {tag}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <label className="cursor-pointer block">
            <div className="flex items-center justify-center gap-2 border-2 border-dashed border-primary/30 rounded-xl px-4 py-5 hover:bg-secondary/30 transition-colors">
              <Upload className="w-5 h-5 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">{uploading ? 'Subiendo...' : 'Selecciona archivo para subir'}</span>
            </div>
            <input type="file" multiple className="hidden" onChange={handleUpload} disabled={uploading} />
          </label>
        </div>
      )}

      {/* Filtros */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative flex-1 min-w-[180px]">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <Input placeholder="Buscar documento o etiqueta..." value={search} onChange={e => setSearch(e.target.value)} className="pl-8 h-8 text-xs" />
        </div>
        <Select value={filterCarpeta} onValueChange={setFilterCarpeta}>
          <SelectTrigger className="w-48 h-8 text-xs"><SelectValue placeholder="Carpeta" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Todas las carpetas</SelectItem>
            {CARPETAS.map(c => <SelectItem key={c.value} value={c.value} className="text-xs">{c.label}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={filterEstado} onValueChange={setFilterEstado}>
          <SelectTrigger className="w-32 h-8 text-xs"><SelectValue placeholder="Estado" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Todos</SelectItem>
            {Object.keys(ESTADO_COLORS).map(k => <SelectItem key={k} value={k} className="capitalize text-xs">{k}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <div className="p-8 text-center"><div className="w-5 h-5 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" /></div>
      ) : filtered.length === 0 ? (
        <p className="text-sm text-muted-foreground text-center py-8">Sin documentos en el archivo.</p>
      ) : (
        <div className="space-y-4">
          {CARPETAS.filter(c => grouped[c.value]?.length > 0).map(carpeta => (
            <div key={carpeta.value} className="bg-card border border-border rounded-xl overflow-hidden">
              <div className="px-4 py-2.5 bg-secondary/30 border-b border-border">
                <p className="text-xs font-semibold text-foreground">{carpeta.label}</p>
              </div>
              <div className="divide-y divide-border">
                {grouped[carpeta.value].map(doc => (
                  <div key={doc.id} className={cn('flex items-center gap-3 px-4 py-2.5', doc.estado === 'sustituido' && 'opacity-50')}>
                    <FileText className="w-4 h-4 text-muted-foreground flex-shrink-0" />
                    <div className="flex-1 min-w-0">
                      <p className={cn('text-sm font-medium truncate', doc.estado === 'sustituido' && 'line-through text-muted-foreground')}>{doc.nombre}</p>
                      <div className="flex items-center gap-2 flex-wrap mt-0.5">
                        <span className="text-[10px] text-muted-foreground">{fmtDate(doc.fechaSubida)} · v{doc.version} · {doc.subidoPor}</span>
                        {(doc.etiquetas || []).map(tag => (
                          <span key={tag} className="text-[9px] bg-secondary px-1.5 py-0.5 rounded text-muted-foreground flex items-center gap-0.5">
                            <Tag className="w-2 h-2" />{tag}
                          </span>
                        ))}
                      </div>
                    </div>
                    <Select value={doc.estado} onValueChange={v => updateEstado(doc, v)}>
                      <SelectTrigger className={cn('h-6 w-24 text-[10px] border rounded-full', ESTADO_COLORS[doc.estado])}><SelectValue /></SelectTrigger>
                      <SelectContent>
                        {Object.keys(ESTADO_COLORS).map(k => <SelectItem key={k} value={k} className="text-xs capitalize">{k}</SelectItem>)}
                      </SelectContent>
                    </Select>
                    {doc.fileUrl && (
                      <a href={doc.fileUrl} target="_blank" rel="noopener noreferrer" className="text-primary hover:text-primary/80 flex-shrink-0">
                        <ExternalLink className="w-3.5 h-3.5" />
                      </a>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

src/components/mercantil/MercantilLibros:
import { uploadRelatedDocument } from '@/lib/privateDocuments';
import { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Upload, CheckCircle, AlertTriangle, ExternalLink } from 'lucide-react';
import { cn } from '@/lib/utils';

const LIBROS_CONFIG = [
  { tipo: 'diario', label: 'Libro Diario' },
  { tipo: 'inventarios_cuentas', label: 'Libro de Inventarios y Cuentas Anuales' },
  { tipo: 'balance_situacion', label: 'Balance de Situación' },
  { tipo: 'pyg', label: 'Cuenta de Pérdidas y Ganancias' },
  { tipo: 'balance_sumas_saldos', label: 'Balance de Sumas y Saldos' },
  { tipo: 'socios', label: 'Libro de Socios' },
  { tipo: 'actas', label: 'Libro de Actas' },
  { tipo: 'otros', label: 'Otros libros' },
];

const ESTADO_CFG = {
  pendiente:     { label: 'Pendiente',    color: 'bg-slate-100 text-slate-600' },
  preparado:     { label: 'Preparado',    color: 'bg-blue-100 text-blue-700' },
  revisado:      { label: 'Revisado',     color: 'bg-indigo-100 text-indigo-700' },
  presentado:    { label: 'Presentado',   color: 'bg-amber-100 text-amber-700' },
  legalizado:    { label: 'Legalizado ✓', color: 'bg-emerald-100 text-emerald-700' },
  con_incidencia:{ label: 'Incidencia',   color: 'bg-red-100 text-red-700' },
};

function UploadBtn({ label, url, onUpload, disabled, sociedadId }) {
  const [uploading, setUploading] = useState(false);
  const handle = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    const { file_url } = await uploadRelatedDocument({file,contextKind:'mercantil',contextId:sociedadId});
    await onUpload(file_url);
    setUploading(false);
  };
  return (
    <div className="flex items-center gap-1.5">
      {url ? (
        <a href={url} target="_blank" rel="noopener noreferrer"
          className="text-[10px] text-primary underline flex items-center gap-0.5">
          Ver <ExternalLink className="w-2.5 h-2.5" />
        </a>
      ) : null}
      <label className={cn('cursor-pointer text-[10px] text-muted-foreground hover:text-foreground flex items-center gap-0.5 border border-dashed border-border rounded px-1.5 py-0.5', disabled && 'opacity-40 pointer-events-none')}>
        <Upload className="w-2.5 h-2.5" />
        {uploading ? 'Subiendo...' : (url ? 'Actualizar' : label)}
        <input type="file" className="hidden" onChange={handle} disabled={disabled || uploading} />
      </label>
    </div>
  );
}

export default function MercantilLibrosTab({ expediente, isAdmin, user, onRefresh }) {
  const [libros, setLibros] = useState([]);
  const [loading, setLoading] = useState(true);
  const [confirmacionRM, setConfirmacionRM] = useState({ registroMercantil: '', numPresentacion: '', fechaPresentacion: '', fechaLegalizacion: '', resultado: '', observaciones: '' });
  const [savingRM, setSavingRM] = useState(false);

  const load = async () => {
    setLoading(true);
    const data = await base44.entities.MercantilLibro.filter({ expedienteId: expediente.id }).catch(() => []);
    // Ensure all libro types exist
    const existing = (data || []);
    const missing = LIBROS_CONFIG.filter(lc => !existing.find(l => l.tipoLibro === lc.tipo));
    if (missing.length > 0) {
      const created = await base44.entities.MercantilLibro.bulkCreate(
        missing.map(lc => ({ expedienteId: expediente.id, sociedadId: expediente.sociedadId, tipoLibro: lc.tipo, aplica: true, estado: 'pendiente' }))
      ).catch(() => []);
      setLibros([...existing, ...(created || [])]);
    } else {
      setLibros(existing);
    }
    // Load RM confirmation from expediente
    setConfirmacionRM({
      registroMercantil: expediente.registroMercantilRef || '',
      numPresentacion: expediente.numPresentacionLibros || '',
      fechaPresentacion: expediente.fechaPresentacionLibros || '',
      fechaLegalizacion: expediente.fechaLegalizacionLibros || '',
      resultado: expediente.resultadoLibros || '',
      observaciones: '',
    });
    setLoading(false);
  };

  useEffect(() => { if (expediente) load(); }, [expediente.id]);

  const updateLibro = async (libro, changes) => {
    await base44.entities.MercantilLibro.update(libro.id, changes);
    setLibros(prev => prev.map(l => l.id === libro.id ? { ...l, ...changes } : l));
    await base44.entities.MercantilHistorial.create({
      expedienteId: expediente.id, sociedadId: expediente.sociedadId,
      fecha: new Date().toISOString(), usuario: user?.email || 'admin',
      accion: `Libro "${LIBROS_CONFIG.find(c => c.tipo === libro.tipoLibro)?.label}": ${JSON.stringify(changes)}`,
      tipoAccion: 'cambio_estado',
    });
  };

  const saveRM = async () => {
    setSavingRM(true);
    await base44.entities.MercantilExpediente.update(expediente.id, {
      registroMercantilRef: confirmacionRM.registroMercantil,
      numPresentacionLibros: confirmacionRM.numPresentacion,
      fechaPresentacionLibros: confirmacionRM.fechaPresentacion,
      fechaLegalizacionLibros: confirmacionRM.fechaLegalizacion,
      resultadoLibros: confirmacionRM.resultado,
      ultimaActualizacion: new Date().toISOString(),
    });
    setSavingRM(false);
    onRefresh?.();
  };

  if (loading) return <div className="p-8 text-center"><div className="w-5 h-5 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" /></div>;

  const sortedLibros = LIBROS_CONFIG.map(lc => libros.find(l => l.tipoLibro === lc.tipo)).filter(Boolean);

  return (
    <div className="space-y-5">
      {/* Checklist libros */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        <div className="px-4 py-3 border-b border-border bg-secondary/30">
          <h3 className="text-sm font-semibold text-foreground">Libros contables y societarios</h3>
          <p className="text-xs text-muted-foreground">Marca estado, sube archivos fuente y justificantes por libro.</p>
        </div>
        <div className="divide-y divide-border overflow-x-auto">
          <div className="grid grid-cols-[2fr_1fr_80px_1fr_1fr_1fr_1fr] gap-2 px-4 py-2 bg-secondary/20 text-[10px] font-semibold text-muted-foreground uppercase tracking-wide min-w-[900px]">
            <span>Libro</span><span>Estado</span><span>Aplica</span><span>Fuente / PDF</span><span>Justificante</span><span>Confirmación RM</span><span>Fechas</span>
          </div>
          {sortedLibros.map(libro => {
            const cfg = LIBROS_CONFIG.find(c => c.tipo === libro.tipoLibro);
            return (
              <div key={libro.id} className={cn('grid grid-cols-[2fr_1fr_80px_1fr_1fr_1fr_1fr] gap-2 px-4 py-3 items-center min-w-[900px]', !libro.aplica && 'opacity-40')}>
                <span className={cn('text-xs font-medium', libro.estado === 'legalizado' ? 'text-emerald-700' : 'text-foreground')}>
                  {libro.estado === 'legalizado' && <CheckCircle className="w-3 h-3 inline mr-1 text-emerald-500" />}
                  {libro.estado === 'con_incidencia' && <AlertTriangle className="w-3 h-3 inline mr-1 text-red-500" />}
                  {cfg?.label}
                </span>
                <Select value={libro.estado} onValueChange={v => updateLibro(libro, { estado: v })}>
                  <SelectTrigger className="h-7 text-[11px] w-full">
                    <span className={cn('text-[10px] font-medium px-1.5 py-0.5 rounded', ESTADO_CFG[libro.estado]?.color)}>{ESTADO_CFG[libro.estado]?.label}</span>
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(ESTADO_CFG).map(([k, v]) => <SelectItem key={k} value={k} className="text-xs">{v.label}</SelectItem>)}
                  </SelectContent>
                </Select>
                <label className="flex items-center gap-1 cursor-pointer">
                  <input type="checkbox" checked={!!libro.aplica} onChange={e => updateLibro(libro, { aplica: e.target.checked })} className="w-3.5 h-3.5" />
                  <span className="text-[10px] text-muted-foreground">{libro.aplica ? 'Aplica' : 'N/A'}</span>
                </label>
                <UploadBtn sociedadId={expediente.sociedadId} label="Subir fuente" url={libro.archivoFuenteUrl} disabled={!libro.aplica}
                  onUpload={url => updateLibro(libro, { archivoFuenteUrl: url })} />
                <UploadBtn sociedadId={expediente.sociedadId} label="Justificante" url={libro.justificantePresentacionUrl} disabled={!libro.aplica}
                  onUpload={url => updateLibro(libro, { justificantePresentacionUrl: url })} />
                <UploadBtn sociedadId={expediente.sociedadId} label="Confirma. RM" url={libro.confirmacionRegistroUrl} disabled={!libro.aplica}
                  onUpload={url => updateLibro(libro, { confirmacionRegistroUrl: url })} />
                <div className="space-y-0.5 text-[10px] text-muted-foreground">
                  <div>Prep: <Input type="date" value={libro.fechaPreparacion || ''} onChange={e => updateLibro(libro, { fechaPreparacion: e.target.value })} className="h-5 text-[10px] border-0 p-0 w-24 inline-block" /></div>
                  <div>Pres: <Input type="date" value={libro.fechaPresentacion || ''} onChange={e => updateLibro(libro, { fechaPresentacion: e.target.value })} className="h-5 text-[10px] border-0 p-0 w-24 inline-block" /></div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Confirmación RM */}
      <div className="bg-card border border-border rounded-xl p-5 space-y-4">
